  3	public enum OrderStatus {
  4	  AWAITING_PAYMENT,
  5	  PAID,
  6	  SHIPPED,
  7	  DELIVERED,
  8	  CANCELLED;
  9	
 10	  public boolean canTransitionTo(OrderStatus newStatus) {
 11	    if (this == newStatus) return true;
 12	
 13	    return switch (this) {
 14	      case AWAITING_PAYMENT -> newStatus == PAID || newStatus == CANCELLED;
 15	      case PAID -> newStatus == SHIPPED || newStatus == CANCELLED;
 16	      case SHIPPED -> newStatus == DELIVERED;
 17	      case DELIVERED, CANCELLED -> false;
 18	    };
 19	  }
 20	}
