  1	package com.loja.order.service;
  2	
  3	import com.loja.order.domain.*;
  4	import com.loja.order.dto.*;
  5	import com.loja.order.model.*;
  6	import com.loja.order.repository.*;
  7	import jakarta.transaction.Transactional;
  8	import org.springframework.stereotype.Service;
  9	import java.math.BigDecimal;
 10	import java.time.Instant;
 11	import java.util.ArrayList;
 12	import java.util.List;
 13	import java.util.Optional;
 14	
 15	@Service
 16	public class OrderService {
 17	  private final OrderRepository orderRepository;
 18	  private final ProductRepository productRepository;
 19	  private final CustomerRepository customerRepository;
 20	  private final NotificationRepository notificationRepository;
 21	  private final PricingService pricingService;
 22	  private final TransLogClient transLogClient;
 23	
 24	  public OrderService(
 25	    OrderRepository orderRepository,
 26	    ProductRepository productRepository,
 27	    CustomerRepository customerRepository,
 28	    NotificationRepository notificationRepository,
 29	    PricingService pricingService,
 30	    TransLogClient transLogClient
 31	  ) {
 32	    this.orderRepository = orderRepository;
 33	    this.productRepository = productRepository;
 34	    this.customerRepository = customerRepository;
 35	    this.notificationRepository = notificationRepository;
 36	    this.pricingService = pricingService;
 37	    this.transLogClient = transLogClient;
 38	  }
 39	
 40	  public SummaryResponse calculateSummary(OrderRequest request) throws ValidationException, ServiceException {
 41	    validateRequest(request);
 42	
 43	    List<PricingService.SummaryItem> items = new ArrayList<>();
 44	    BigDecimal totalWeight = BigDecimal.ZERO;
 45	
 46	    for (OrderRequest.ItemRequest itemReq : request.items()) {
 47	      Product product = productRepository.findById(itemReq.sku())
 48	        .orElseThrow(() -> new ValidationException("UNKNOWN_PRODUCT"));
 49	
 50	      if (product.isDiscontinued()) {
 51	        throw new ValidationException("PRODUCT_DISCONTINUED");
 52	      }
 53	
 54	      items.add(new PricingService.SummaryItem(
 55	        itemReq.sku(),
 56	        itemReq.quantity(),
 57	        product.getPrice()
 58	      ));
 59	
 60	      totalWeight = totalWeight.add(
 61	        product.getWeightKg().multiply(new BigDecimal(itemReq.quantity()))
 62	      );
 63	    }
 64	
 65	    ShippingMethod shippingMethod = parseShippingMethod(request.shippingMethod());
 66	    Region region = parseRegion(request.region());
 67	
 68	    checkShippingAvailability(shippingMethod, totalWeight, request.zipCode());
 69	
 70	    BigDecimal shippingCost = BigDecimal.ZERO;
 71	    int deliveryDays = 0;
 72	
 73	    if (shippingMethod == ShippingMethod.STORE_PICKUP) {
 74	      deliveryDays = 1;
 75	    } else if (shippingMethod == ShippingMethod.COURIER) {
 76	      shippingCost = new BigDecimal("18.00");
 77	      deliveryDays = 0;
 78	    } else {
 79	      try {
 80	        String service = shippingMethod == ShippingMethod.ECONOMY ? "STD" : "EXP";
 81	        TransLogClient.QuoteResponse quote = transLogClient.quote(
 82	          request.zipCode(),
 83	          totalWeight.intValue() * 1000,
 84	          service
 85	        );
 86	        shippingCost = quote.price();
 87	        deliveryDays = quote.etaDays() + region.getCarrierDaysAddition(shippingMethod);
 88	      } catch (TransLogClient.ZipCodeNotServedException e) {
 89	        throw new ValidationException("SHIPPING_METHOD_UNAVAILABLE");
 90	      } catch (TransLogClient.TransLogUnavailableException e) {
 91	        throw new ServiceException("CARRIER_UNAVAILABLE");
 92	      } catch (Exception e) {
 93	        throw new ServiceException("CARRIER_UNAVAILABLE");
 94	      }
 95	    }
 96	
 97	    ClubTier clubTier = parseClubTier(request.clubTier());
 98	    PaymentMethod paymentMethod = parsePaymentMethod(request.paymentMethod());
 99	    int installments = request.installments() != null ? request.installments() : 1;
100	
101	    validatePaymentMethod(paymentMethod, installments);
102	
103	    boolean isFirstPurchase = !orderRepository.hasCompletedOrders(request.customer().cpf());
104	
105	    BigDecimal productsSubtotal = calculateProductsSubtotal(items);
106	
107	    validateCoupon(request.coupon(), items, isFirstPurchase);
108	
109	    OrderSummary summary = pricingService.calculateSummary(
110	      items,
111	      request.coupon(),
112	      shippingMethod,
113	      shippingCost,
114	      deliveryDays,
115	      region,
116	      paymentMethod,
117	      installments,
118	      clubTier,
119	      isFirstPurchase
120	    );
121	
122	    if (paymentMethod == PaymentMethod.BANK_SLIP && summary.getFinalTotal().compareTo(new BigDecimal("1000.00")) > 0) {
123	      throw new ValidationException("PAYMENT_METHOD_UNAVAILABLE");
124	    }
125	
126	    return new SummaryResponse(
127	      summary.getProductsSubtotal(),
128	      summary.getCouponDiscount(),
129	      summary.getShippingCost(),
130	      summary.getDeliveryDays(),
131	      summary.getInsurance(),
132	      summary.getPaymentAdjustment(),
133	      summary.getFinalTotal(),
134	      summary.getInstallments(),
135	      summary.getInstallmentAmount(),
136	      summary.getNextPurchaseCredit(),
137	      summary.isGift()
138	    );
139	  }
140	
141	  @Transactional
142	  public OrderResponse createOrder(OrderRequest request) throws ValidationException, ServiceException {
143	    SummaryResponse summary = calculateSummary(request);
144	
145	    Order order = new Order(
146	      request.customer().cpf(),
147	      request.customer().email(),
148	      parseRegion(request.region()),
149	      parseShippingMethod(request.shippingMethod()),
150	      request.zipCode(),
151	      parsePaymentMethod(request.paymentMethod()),
152	      request.installments() != null ? request.installments() : 1,
153	      parseClubTier(request.clubTier()),
154	      request.coupon()
155	    );
156	
157	    for (OrderRequest.ItemRequest itemReq : request.items()) {
158	      Product product = productRepository.findById(itemReq.sku())
159	        .orElseThrow(() -> new ValidationException("UNKNOWN_PRODUCT"));
