322	  private void validateRequest(OrderRequest request) throws ValidationException {
323	    if (request.customer() == null || request.customer().cpf() == null || request.customer().email() == null) {
324	      throw new ValidationException("INVALID_ORDER");
325	    }
326	
327	    if (request.items() == null || request.items().isEmpty()) {
328	      throw new ValidationException("INVALID_ORDER");
329	    }
330	
331	    for (OrderRequest.ItemRequest item : request.items()) {
332	      if (item.sku() == null || item.quantity() == null || item.quantity() <= 0) {
333	        throw new ValidationException("INVALID_ORDER");
334	      }
335	    }
336	
337	    if (request.zipCode() == null || request.zipCode().isEmpty()) {
338	      throw new ValidationException("INVALID_ZIP_CODE");
339	    }
340	
341	    for (OrderRequest.ItemRequest itemReq : request.items()) {
342	      if (request.items().stream().filter(i -> i.sku().equals(itemReq.sku())).count() > 1) {
343	        throw new ValidationException("INVALID_ORDER");
344	      }
345	
346	      Product product = productRepository.findById(itemReq.sku()).orElse(null);
347	      if (product == null) {
348	        throw new ValidationException("UNKNOWN_PRODUCT");
349	      }
