357	  private void validateCoupon(String coupon, List<PricingService.SummaryItem> items, boolean isFirstPurchase)
358	    throws ValidationException {
359	    if (coupon == null || coupon.isEmpty()) {
360	      return;
361	    }
362	
363	    Optional<Coupon> couponOpt = Coupon.fromCode(coupon);
364	    if (!couponOpt.isPresent()) {
365	      throw new ValidationException("INVALID_COUPON");
366	    }
367	
368	    Coupon couponEnum = couponOpt.get();
369	    BigDecimal subtotal = items.stream()
370	      .map(item -> item.price().multiply(new BigDecimal(item.quantity())))
371	      .reduce(BigDecimal.ZERO, BigDecimal::add);
372	
373	    List<Coupon.OrderItem> couponItems = items.stream()
374	      .map(item -> new Coupon.OrderItem(item.sku(), item.quantity(), item.price()))
375	      .toList();
376	
377	    Coupon.OrderContext ctx = new Coupon.OrderContext(
378	      couponItems,
379	      isFirstPurchase,
380	      ShippingMethod.STORE_PICKUP,
381	      BigDecimal.ZERO
382	    );
383	
384	    if (couponEnum.calculateDiscount(subtotal, ctx).isEmpty()) {
385	      throw new ValidationException("COUPON_NOT_APPLICABLE");
386	    }
387	  }
